const input = Number(msg.payload);
let total = 0;
const squares = [];

for (let i = 1; i <= input; i++) {
    const square = i * i;
    squares.push(square);
    total += square;
}

let category;
if (total >= 50) {
    category = "большой результат";
} else {
    category = "малый результат";
}

const result = {
    student: "Sandrakula",
    input: input,
    squares: squares,
    total: total,
    category: category
};

msg.payload = result;
return msg;
